"""Specs for the remaining catalog categories: Stations, Blocks, Gatherables, Armor, Town, Vehicles, Sky and the rest of
the Dragon Warrior realm. GROUPS are the build batches, in Richey's order. Front = -Y, origin bottom-centre, 1 m units.
Shapes are small parametric families (lump, gem, ingot, bottle, log, seed, fruit...) so a whole category stays consistent."""
from assets.catalog import ASSETS
from assets.ecospecs import TREES, CROP, FLOWER, h

def b(s, c, m=0): return [list(s), list(c), m]
def P(name, boxes, pivot=None):
    d = {"name": name, "boxes": boxes}
    if pivot is not None: d["pivot"] = list(pivot)
    return d
def S(asset, mats, parts, glow=(), bevel=0.12):
    return {"asset": asset, "materials": list(mats), "glow": list(glow), "parts": parts if isinstance(parts[0], dict) else [P("", parts)], "bevel": bevel}

