def station(n):
    v = STATIONS[n]; mats, boxes = v[0], v[1]; glow = v[2] if len(v) > 2 and v[2] else []
    parts = [P("", boxes)] + (v[3] if len(v) > 3 else [])
    return S(n, mats, parts, glow=glow)

