def block(n):
    if n in ("Prop_Door", "Prop_Door_Wood"): return S(n, (WOOD, DWOOD, "F2C230"), door(0, 0))
    if n == "Prop_Door_Iron": return S(n, (IRON, "7D7B84", DARK), door(0, 0, iron=True))
    if n == "Prop_Chest": return S(n, (WOOD, DWOOD, "F2C230"), chest(1.0))
    if n == "Prop_Chest_Large": return S(n, (WOOD, DWOOD, "F2C230"), chest(2.0))
    v = BLOCKS[n]; return S(n, v[0], v[1], glow=v[2] if len(v) > 2 else [])

