def roofhouse(w, d, hgt, wall, roof, trim, sign=None):
    bx = [b((w, d, hgt), (0, 0, hgt / 2), 0), b((w + 0.2, d + 0.2, 0.2), (0, 0, 0.1), 2)]
    for i in range(5):   # stepped gable roof
        rw = w + 0.6 - i * (w + 0.6) / 5
        bx.append(b((rw, d + 0.5, 0.45), (0, 0, hgt + 0.22 + 0.45 * i), 1))
    bx += [b((1.0, 0.1, 1.9), (0, -d / 2 - 0.04, 0.95), 2), b((0.8, 0.12, 0.8), (-w / 3, -d / 2 - 0.04, hgt * 0.6), 2), b((0.8, 0.12, 0.8), (w / 3, -d / 2 - 0.04, hgt * 0.6), 2),
           b((0.6, 0.6, 1.2), (w / 3, d / 4, hgt + 1.4), 0)]
    if sign: bx += [b((w * 0.6, 0.12, 0.6), (0, -d / 2 - 0.1, hgt - 0.3), 2)]
    return bx
