def chunk(n, s, seed):
    bx = []
    for i in range(9):
        w = s * (0.35 + 0.4 * h(n, i)); d = s * (0.35 + 0.4 * h(n, i + 20)); t = s * (0.3 + 0.35 * h(n, i + 40))
        bx.append(b((w, d, t), (s * (h(n, i + 60) - 0.5) * 0.6, s * (h(n, i + 80) - 0.5) * 0.6, s * 0.15 + s * 0.55 * h(n, i + 99)), 0 if i % 3 else 1))
    bx += [b((s * 0.12, s * 0.12, s * 0.2), (s * (h(n, k) - 0.5) * 0.7, -s * 0.35, s * (0.2 + 0.5 * h(n, k + 7))), 2) for k in range(3)]
    return bx
def sky(n):
    if n == "Sky_ShatteredPlanet":
        R = 40.0; bx = []
        for i in range(10):
            import math
            a = 2 * math.pi * i / 10; rr = R * (0.85 + 0.2 * h(n, i))
            bx.append(b((R * 0.5, R * 0.5, R * 0.5 * (0.6 + 0.6 * h(n, i + 3))), (rr * math.cos(a) * 0.6, rr * math.sin(a) * 0.6, R * 0.5 + R * 0.4 * math.sin(a * 2)), i % 2))
        bx += [b((R * 0.7, R * 0.7, R * 0.7), (0, 0, R * 0.5), 2), b((R * 1.6, R * 0.1, R * 0.04), (0, 0, R * 0.5), 1), b((R * 0.1, R * 1.6, R * 0.04), (0, 0, R * 0.5), 1)]
        return S(n, ("7D7B84", "5C389E", "F87818"), [P("", [x for x in bx[:-3]]), P("_Core", bx[-3:], (0, 0, R * 0.5))], glow=[2], bevel=0.1)
    s = {"A": 8.0, "B": 12.0, "C": 18.0}[n[-1]]
    return S(n, ("6B6470", "4A4D57", "7FE3FF"), chunk(n, s, 0), glow=[2], bevel=0.1)

